"""gen_mac_imptab.py <out.c> <files...>: sorted table of the native import implementations: IMP(symbol) and
IMP_AS(cname, "symbol$VARIANT") definitions in runtime/mac/*.c."""
import sys, re
rows = {}
for p in sys.argv[2:]:
    src = open(p).read()
    for m in re.finditer(r'^IMP\((\w+)\)', src, re.M): rows[m.group(1)] = 'imp_' + m.group(1)
    for m in re.finditer(r'^IMP_AS\((\w+),\s*"([^"]+)"\)', src, re.M): rows[m.group(2)] = 'imp_' + m.group(1)
    # implementations generated by a macro: '#define NAME(K, P)' whose body has IMP(P##...##K...) lines, and
    # NAME(k, prefix) invocations at the start of a line
    for d in re.finditer(r'^#define (\w+)\((\w+), (\w+)\)((?:.*\\\n)+.*)', src, re.M):
        name, ka, pa, body = d.groups()
        tmpl = re.findall(r'IMP\(([^)]*)\)', body)
        for inv in re.finditer(r'^%s\((\w+), (\w+)\)' % name, src, re.M):
            kv, pv = inv.groups()
            for t in tmpl:
                sym = ''.join(pv if x == pa else kv if x == ka else x for x in re.split(r'\s*##\s*', t))
                rows[sym] = 'imp_' + sym
    for m in re.finditer(r'^ALIAS\((\w+),\s*"([^"]+)"\)', src, re.M): rows[m.group(2)] = 'imp_' + m.group(1)   # second name, same function
    for m in re.finditer(r'^OVR\((\w+)\)', src, re.M): rows['=' + m.group(1)] = 'ovr_' + m.group(1)   # function replacements
names = sorted(rows, key=lambda s: s.encode())
with open(sys.argv[1], 'w') as o:
    o.write('#include "mac.h"\n')
    for f in sorted(set(rows.values())): o.write('void %s(Ctx *c);\n' % f)
    o.write('const struct mac_impl { const char *name; void (*fn)(Ctx *); } mac_impls[] = {\n')
    for n in names: o.write('    {"%s", %s},\n' % (n, rows[n]))
    o.write('};\nconst unsigned mac_nimpls = %d;\n' % len(names))
print('%d imports implemented' % len(names))
